112→/** Effective license state incl. expiry that lapsed while status still says "active". */
113→export function licenseState(lic?: LicenseRecord | null): ClientLicenseState {
114→  if (!lic) {
115→    return {
116→      id: null, status: "none", effective: "none", expiresAt: null, lifetime: false,
117→      daysLeft: null, expiringSoon: false, keyLast4: null, maskedKey: null,
118→      activationCount: 0, activationLimit: 0, lastSeenAt: null, billingCycle: null,
119→    };
120→  }
121→  const lifetime = !lic.expires_at;
122→  const rawStatus = String(lic.status || "none");
123→  const expired = isExpiredStatus(lic.status as any, lic.expires_at);
124→  const effective: ClientLicenseState["effective"] = expired
125→    ? "expired"
126→    : rawStatus === "trial"
127→      ? "active"
128→      : (["active", "suspended", "revoked", "cancelled"].includes(rawStatus)
129→        ? (rawStatus as ClientLicenseState["effective"])
130→        : "none");
131→  const daysLeft = lifetime
132→    ? null
133→    : Math.ceil((new Date(lic.expires_at as string).getTime() - Date.now()) / 86_400_000);
134→  return {
135→    id: lic.id,
136→    status: rawStatus,
137→    effective,
138→    expiresAt: lic.expires_at,
139→    lifetime,
140→    daysLeft,
141→    expiringSoon: daysLeft !== null && daysLeft >= 0 && daysLeft <= 7,
142→    keyLast4: lic.key_last4 || null,
143→    maskedKey: lic.key_last4 ? maskLicenseKey(`${lic.key_last4}`) : null,
144→    activationCount: Number(lic.activation_count || 0),
145→    activationLimit: Number(lic.activation_limit || 0),
146→    lastSeenAt: lic.last_seen_at || null,
147→    billingCycle: lic.billing_cycle || null,
148→  };
149→}
