168→/** POST any agent action with the site's handshake token (never exposes the token). */
169→export async function agentCall(
170→  site: Site,
171→  action: string,
172→  extra: Record<string, unknown> = {},
173→  timeoutMs = 20_000
174→): Promise<{ ok: boolean; data: any; error: string }> {
175→  const agentUrl = getAuthPhpUrl(site.domain, site.path);
176→  if (!agentUrl) return { ok: false, data: null, error: "No agent URL could be built for this site." };
177→  try {
178→    const res = await fetch(`${agentUrl}?action=${encodeURIComponent(action)}`, {
179→      method: "POST",
180→      headers: { "Content-Type": "application/json", "X-Slate-Token": site.handshakeToken },
181→      body: JSON.stringify({ action, token: site.handshakeToken, ...extra }),
182→      signal: AbortSignal.timeout(timeoutMs),
183→    });
184→    const text = await res.text();
185→    let data: any = {};
186→    try { data = JSON.parse(text); } catch { data = { raw: text.slice(0, 400) }; }
187→    if (!res.ok || data?.error) {
188→      return { ok: false, data, error: data?.error || `Agent HTTP ${res.status}.` };
189→    }
190→    return { ok: true, data, error: "" };
191→  } catch (err: any) {
192→    return { ok: false, data: null, error: err?.message || "Agent unreachable." };
193→  }
194→}
