684→/** Read the client's live license status and sync the Master registry + site badge. */
685→export async function syncLicenseFromAgent(site: Site) {
686→  const res = await agentCall(site, "license_status");
687→  if (!res.ok) {
688→    await updateSite(site.id, { licenseStatus: "OFFLINE" }).catch(() => null);
689→    return { ok: false, message: res.error, license: null, siteLicenseStatus: "OFFLINE" };
690→  }
