692→  const map: Record<string, string> = {
693→    active: "ACTIVE", trial: "ACTIVE", expired: "EXPIRED", suspended: "SUSPENDED", revoked: "REVOKED",
694→  };
695→  const status = map[String(lic.status)] || "NONE";
696→  await updateSite(site.id, { licenseStatus: status as any }).catch(() => null);
697→  if (site.licenseId) {
698→    await updateLicense(site.licenseId, { last_seen_at: new Date().toISOString() }).catch(() => null);
699→  }
700→  return {
701→    ok: true,
702→    message: `Agent reports license ${String(lic.status || "unknown")} (${status}).`,
703→    license: lic,
704→    siteLicenseStatus: status,
705→  };
706→}
