708→/** Delete a client: the order + all its licenses always; the site only when asked. */
709→export async function deleteClientRecord(id: string, opts: { removeSite?: boolean } = {}) {
710→  const order = await getOrder(id);
711→  const directSite = await getSite(id);
712→  const site = order?.siteId ? (await getSite(order.siteId)) || directSite : directSite;
713→  const licenses = await getLicenses();
714→
715→  const licenseIds = new Set<string>();
716→  for (const l of licenses) {
717→    if (l.id === id || l.orderId === id || (site && l.siteId === site.id) || (order?.licenseId && l.id === order.licenseId)) {
718→      licenseIds.add(l.id);
719→    }
720→  }
721→  if (!order && !site && licenseIds.size === 0) return null;
722→
723→  let licensesRemoved = 0;
724→  for (const lid of Array.from(licenseIds)) licensesRemoved += (await deleteLicense(lid)) ? 1 : 0;
725→
726→  let siteDeleted = false;
727→  if (site) {
728→    await deleteDeploymentsForSite(site.id);
729→    if (opts.removeSite) {
730→      siteDeleted = await deleteSite(site.id);
731→    } else {
732→      await updateSite(site.id, { licenseId: undefined, licenseStatus: "NONE" as any }).catch(() => null);
733→    }
734→  }
735→
736→  const orderDeleted = order ? await deleteOrder(order.id) : false;
737→  return {
738→    orderId: order?.id || null,
739→    siteId: site?.id || null,
740→    siteDeleted,
741→    orderDeleted,
742→    licensesRemoved,
743→  };
744→}
